package de.teamlapen.faction.common.factions.tasks;

import com.google.common.base.Objects;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import de.teamlapen.faction.api.FactionRegistries;
import de.teamlapen.faction.api.factions.tasks.ITaskInstance;
import de.teamlapen.faction.api.factions.tasks.ITaskRewardInstance;
import de.teamlapen.faction.api.factions.tasks.Task;
import de.teamlapen.faction.api.world.entities.player.IFactionPlayer;
import de.teamlapen.faction.common.tags.FactionTaskTags;
import net.minecraft.core.Holder;
import net.minecraft.core.Registry;
import net.minecraft.core.UUIDUtil;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import org.jetbrains.annotations.Nullable;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class TaskInstance implements ITaskInstance {

    public static final Codec<ITaskInstance> CODEC = RecordCodecBuilder.create(inst -> {
        return inst.group(
                UUIDUtil.STRING_CODEC.fieldOf("taskGiver").forGetter(ITaskInstance::getTaskBoard),
                ResourceKey.codec(FactionRegistries.Keys.TASK).fieldOf("task").forGetter(ITaskInstance::getTask),
                UUIDUtil.STRING_CODEC.fieldOf("instanceId").forGetter(ITaskInstance::getId),
                Codec.unboundedMap(Identifier.CODEC, Codec.INT).fieldOf("stats").forGetter(ITaskInstance::getStats),
                ITaskRewardInstance.CODEC.fieldOf("reward").forGetter(ITaskInstance::getReward),
                Codec.LONG.fieldOf("taskDuration").forGetter(ITaskInstance::getTaskDuration),
                Codec.BOOL.fieldOf("accepted").forGetter(ITaskInstance::isAccepted),
                Codec.LONG.fieldOf("taskTimer").forGetter(ITaskInstance::getTaskTimeStamp)
        ).apply(inst, TaskInstance::new);
    });

    private final UUID taskGiver;
    private final ResourceKey<Task> task;
    private final UUID instanceId;
    private final Map<Identifier, Integer> stats;
    private final ITaskRewardInstance reward;
    private final long taskDuration;
    private boolean accepted;
    private long taskTimeStamp;
    private boolean completed;

    public TaskInstance(Holder<Task> task, UUID taskGiver, IFactionPlayer<?> player, long taskDuration) {
        this.task = task.unwrapKey().orElseThrow();
        this.taskGiver = taskGiver;
        this.instanceId = UUID.randomUUID();
        this.stats = new HashMap<>();
        this.taskTimeStamp = -1;
        this.taskDuration = taskDuration;
        this.reward = task.value().reward().createInstance(player);
    }

    private TaskInstance(UUID taskGiver, ResourceKey<Task> task, UUID instanceId, Map<Identifier, Integer> stats, ITaskRewardInstance taskRewardInstance, long taskDuration, boolean accepted, long taskTimeStamp) {
        this.taskGiver = taskGiver;
        this.task = task;
        this.stats = new HashMap<>(stats);
        this.accepted = accepted;
        this.taskTimeStamp = taskTimeStamp;
        this.instanceId = instanceId;
        this.reward = taskRewardInstance;
        this.taskDuration = taskDuration;
    }

    public void abortTask() {
        this.accepted = false;
        this.stats.clear();
        this.taskTimeStamp = -1;
    }

    public void complete() {
        this.completed = true;
    }

    public boolean equals(@Nullable Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        TaskInstance instance = (TaskInstance) o;
        return accepted == instance.accepted && taskTimeStamp == instance.taskTimeStamp && Objects.equal(taskGiver, instance.taskGiver) && Objects.equal(instanceId, instance.instanceId) && Objects.equal(task, instance.task) && Objects.equal(stats, instance.stats);
    }

    public UUID getId() {
        return instanceId;
    }

    @Override
    public ITaskRewardInstance getReward() {
        return this.reward;
    }

    public Map<Identifier, Integer> getStats() {
        return stats;
    }

    public ResourceKey<Task> getTask() {
        return this.task;
    }

    @Override
    public UUID getTaskBoard() {
        return this.taskGiver;
    }

    public long getTaskDuration() {
        return taskDuration;
    }

    public long getTaskTimeStamp() {
        return taskTimeStamp;
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(taskGiver, task, instanceId);
    }

    public boolean isAccepted() {
        return accepted;
    }

    public boolean isCompleted() {
        return completed;
    }

    public boolean isUnique(Registry<Task> registry) {
        return registry.get(this.task).map(s -> s.is(FactionTaskTags.IS_UNIQUE)).orElse(false);
    }

    public void startTask(long timestamp) {
        this.taskTimeStamp = timestamp;
        this.accepted = true;
    }
}

package de.teamlapen.faction.common.factions.tasks;

import com.google.common.collect.Maps;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import de.teamlapen.faction.api.FactionRegistries;
import de.teamlapen.faction.api.factions.IFactionSpecificTags;
import de.teamlapen.faction.api.factions.tasks.*;
import de.teamlapen.faction.api.util.FIdentifier;
import de.teamlapen.faction.api.world.entities.player.IFactionPlayer;
import de.teamlapen.faction.common.config.FactionConfig;
import de.teamlapen.faction.common.core.FactionAttachments;
import de.teamlapen.faction.common.core.FactionStats;
import de.teamlapen.faction.common.factions.FactionExtension;
import de.teamlapen.faction.common.factions.tasks.requirements.ItemRequirement;
import de.teamlapen.faction.common.network.packets.client.ClientboundTaskPacket;
import de.teamlapen.faction.common.network.packets.client.ClientboundTaskStatusPacket;
import de.teamlapen.faction.common.network.packets.server.ServerboundTaskActionPacket;
import de.teamlapen.faction.common.tags.FactionTaskTags;
import de.teamlapen.faction.common.util.collections.CollectionUtil;
import de.teamlapen.faction.common.world.entities.IPlayerEventListener;
import de.teamlapen.faction.common.world.inventory.ITaskMenu;
import de.teamlapen.faction.common.world.inventory.InventoryHelper;
import de.teamlapen.faction.common.world.inventory.TaskBoardMenu;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.stats.Stats;
import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.attachment.IAttachmentHolder;
import net.neoforged.neoforge.attachment.IAttachmentSerializer;
import net.neoforged.neoforge.server.ServerLifecycleHooks;
